std::map<std::string, Specie> Species::EraseMapOfSpeciesEntry
(
   const std::map<std::string, Specie>& species_data_list,
   const std::string& entry
)
{
   std::map<std::string, Specie> out = species_data_list;
   out.erase(entry);
   return out;
}

void Species::UpdateSpecieValues
(
   Specie& output, 
   const Specie& input
)
{
   output.types = input.types.size() > 0 ? input.types : output.types;
   for (auto& [stat, num] : input.bs)
   {
      if (num > 0) output.bs[stat] = num;
   }
   output.weightkg = input.weightkg > 0 ? input.weightkg : output.weightkg;
   if (input.nfe)
   {
      output.nfe = input.nfe;
   }
   if (input.gender)
   {
      output.gender = input.gender;
   }
   if (input.other_formes)
   {
      output.other_formes = input.other_formes;
   }
   if (input.base_species)
   {
      output.base_species = input.base_species;
   }
   if (input.abilities)
   {
      output.abilities = input.abilities;
   }
}

std::map<std::string, Specie> Species::ExtendMapOfSpecie
(
   const std::vector<std::map<std::string, Specie>>& species_data_list
)
{
   std::map<std::string, Specie> out = species_data_list.at(0);
   for (int i = 1; i < species_data_list.size(); i++)
   {
      for (const auto& [key, value] : species_data_list[i])
      {
         if (out.find(key) != out.end())
         {
            Species::UpdateSpecieValues(out.at(key), value);
         }
         else
         {
            out.insert({key, value});
         }
      }
   }

   return out;
}

